from pathlib import Path
p=Path(__file__).resolve().parent
parent=(p.parent/'rain-inexact-lu/run.py').read_text()
split="source=(p.parent/'rain-projected-continuation/run.py').read_text()"
prefix,rest=parent.split(split)
prefix=prefix.replace('A=D[np.ix_(ii,ii)].astype(np.float32)','A=local_matrix(y,lam,ii)')
exec(compile(prefix,str(p/'direction.py'),'exec'))
Spre=np.column_stack([Schur32(np.eye(r.N,dtype=np.float32)[:,i]) for i in range(r.N)])
gpre=m.g.astype(np.float32);basepre=np.zeros(m.offset,dtype=np.float32)
for ii,factor in factors32:basepre[r.free[ii]]=cho_solve(factor,-gpre[r.free[ii]])
qpre=(H32(basepre)+gpre)[r.remaining]
assert Spre.dtype==qpre.dtype==np.float32
local_meta={}
for ii in pre_groups.values():
 ii=np.array(ii);lookup={int(g):i for i,g in enumerate(ii)};blocks=[]
 for b in r.blocks:
  if int(b['indices'][0]) not in lookup:continue
  rows=np.array([lookup[int(g)] for g in b['indices']]);normals=None if b['normal_indices'] is None else np.array([lookup[int(g)] for g in b['normal_indices']]);blocks.append((b,rows,normals))
 assert sum(len(rows) for _,rows,_ in blocks)==len(ii);local_meta[tuple(ii)]=blocks
def local_matrix(y,lam,ii,dtype=np.float32):
 y=np.asarray(y,dtype=dtype);S=Spre if dtype==np.float32 else r.S;q=qpre if dtype==np.float32 else r.q;grad=S@y+q;N=len(ii);E=np.eye(N,dtype=dtype);A=np.zeros((N,N),dtype=dtype)
 for b,rows,normals in local_meta[tuple(ii)]:
  jj=b['indices'];step=dtype(b['step']);z=y[jj]-step*grad[jj];n=len(jj);Dz=np.eye(n,dtype=dtype);Dc=np.zeros(n,dtype=dtype);domain=b['original']['domain']
  cap=dtype(b['original']['cap']) if b['normal_indices'] is None else np.maximum(dtype(0),np.asarray(b['original']['weights'],dtype=dtype)@y[b['normal_indices']])
  if domain=='positive':Dz=np.diag((z>0).astype(dtype))
  elif domain=='box':Dz=np.diag((abs(z)<cap).astype(dtype));Dc=np.where(abs(z)>=cap,np.sign(z),dtype(0))
  elif domain=='ball':
   length=np.linalg.norm(z)
   if length>cap:
    u=z/length;Dz=(cap/length)*(np.eye(n,dtype=dtype)-np.outer(u,u));Dc=u
  A[rows]=dtype(1+lam)*E[rows]-Dz@(E[rows]-step*S[np.ix_(jj,ii)])
  if normals is not None and cap>0:A[np.ix_(rows,normals)]-=np.outer(Dc,np.asarray(b['original']['weights'],dtype=dtype))
 assert A.dtype==dtype and np.all(np.isfinite(A));return A
rnglocal=np.random.default_rng(20261010);errors=[]
for test in range(24):
 y=m.old[r.remaining]+rnglocal.normal(size=r.N)*.1;lam=[1.,.01,0.][test%3];D=r.residual(y,True)+lam*r.E
 for ii in pre_groups.values():
  ii=np.array(ii);want=D[np.ix_(ii,ii)];actual=local_matrix(y,lam,ii,np.float64);errors.append(float(max(abs(actual-want).flat)/(1+max(abs(want).flat))))
assert max(errors)<=1e-9
(p/'local-controls.json').write_text(json.dumps(dict(states=24,blocks=len(errors),max_algebra_error=max(errors)),indent=2))
source_part=split+rest
exec(compile(source_part,str(p/'nonlinear.py'),'exec'))
if not all(v['status']=='reference-pass' for v in results.values()):raise SystemExit(1)

